import json, re, subprocess

def load(text):
    return [json.loads(l) for l in text.splitlines() if l.strip()]

def rowstr(r):
    # every string field of every parsed row (per DOC-19 reasoning's census method)
    out=[]
    def walk(v):
        if isinstance(v,str): out.append(v)
        elif isinstance(v,dict):
            for x in v.values(): walk(x)
        elif isinstance(v,list):
            for x in v: walk(x)
    walk(r)
    return "\n".join(out)

def census(rows, label):
    complete=[r for r in rows if r.get('status') in ('complete','closed')]
    tmp_hits=[]; scratch_hits=[]; commit_hits=[]
    for r in complete:
        s=rowstr(r)
        for m in re.findall(r'(?:prompt|evidence)=/tmp\S*', s): tmp_hits.append((r['id'],m))
        for m in re.findall(r'witness=live:scratch\S*', s): scratch_hits.append((r['id'],m))
        for m in re.findall(r'witness=commit:\S*', s): commit_hits.append((r['id'],m))
    rowcount=sum(len(re.findall(r'row=', rowstr(r))) for r in rows)
    chtrace=sum(len(re.findall(r'ch:trace', rowstr(r))) for r in rows)
    print(f"== {label}")
    print("rows:", len(rows), "complete/closed rows:", len(complete))
    print("(prompt|evidence)=/tmp on complete/closed:", len(tmp_hits), "in", len(set(i for i,_ in tmp_hits)), "rows")
    for i,m in tmp_hits[:30]: print("   ", i, m[:80])
    print("witness=live:scratch on complete/closed:", len(scratch_hits), scratch_hits)
    print("witness=commit: on complete/closed:", len(commit_hits), commit_hits)
    # global (any row) for context
    alltmp=0; allscr=0; allcom=0
    for r in rows:
        s=rowstr(r)
        alltmp+=len(re.findall(r'(?:prompt|evidence)=/tmp', s))
        allscr+=len(re.findall(r'witness=live:scratch', s))
        allcom+=len(re.findall(r'witness=commit:', s))
    print("ALL rows: /tmp markers:", alltmp, " live:scratch:", allscr, " witness=commit:", allcom)
    print("total row= occurrences:", rowcount, "| ch:trace tokens:", chtrace)

